import React, { useState } from 'react';
import styles from '../css/Weather.module.css';

const Weather = () => {
  const [city, setCity] = useState('');
  const [weatherData, setWeatherData] = useState(null);
  const [loading, setLoading] = useState(false);

  const API_KEY = '7ac5efbe309f3e7a20018760eb67b567';

  const fetchWeather = async () => {
    if (!city) {
      alert('도시 이름을 입력하세요.');
      return;
    }

    setLoading(true);

    try {
      // 백엔드로 도시명을 보내 번역된 결과 받기
      const translateResponse = await fetch("http://localhost:8000/weather/translate_city", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ city_name: city }),
      });
      const translateData = await translateResponse.json();

      if (!translateResponse.ok) {
        throw new Error(translateData.detail || "도시명을 변환하는 중 오류 발생");
      }

      const translatedCity = translateData.translated_city;

      // 번역된 도시명으로 날씨 데이터 가져오기
      const response = await fetch(
        `https://api.openweathermap.org/data/2.5/weather?q=${translatedCity}&appid=${API_KEY}&units=metric&lang=kr`
      );
      const data = await response.json();

      if (data.cod === 200) {
        setWeatherData(data);
      } else {
        alert('도시를 찾을 수 없습니다!');
        setWeatherData(null);
      }
    } catch (error) {
      console.error('오류:', error);
      alert(error.message || '문제가 발생했습니다.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.container}>
      <h2>날씨 정보</h2>
      <input
        className={styles.input}
        type="text"
        placeholder="도시 이름 입력"
        value={city}
        onChange={(e) => setCity(e.target.value)}
      />
      <button className={styles.button} onClick={fetchWeather} disabled={loading}>
        {loading ? '불러오는 중...' : '날씨 정보 가져오기'}
      </button>
      {weatherData && (
        <div className={styles['weather-info']}>
          <p>온도: {Math.round(weatherData.main.temp)}°C</p>
          <p>날씨: {weatherData.weather[0].description}</p>
        </div>
      )}
    </div>
  );
};

export default Weather;
